package release

import (
	"github.com/stricttools/strictcli/go/strictcli"
)

// UnreleasedCommit is one commit of a releasable's unreleased range.
type UnreleasedCommit struct {
	Hash    string `json:"hash"`
	Subject string `json:"subject"`
	Author  string `json:"author"`
	// Date is the author date, ISO 8601.
	Date string `json:"date"`
	// Exempt is whether the commit needs no changelog entry (it carries the
	// Autogenerated: true trailer, or changes only rlsbl's own records).
	Exempt bool `json:"exempt"`
	// Covered is whether an unreleased changelog entry names it.
	Covered bool `json:"covered"`
}

// Unreleased is `rlsbl unreleased`'s report: the commits of the selected
// releasable's scope since the nearest release this checkout contains, and
// how its changelog covers them.
type Unreleased struct {
	Releasable string `json:"releasable"`
	LatestFields
	// NearestRelease is the version of the nearest release this checkout
	// contains, which bounds the range; null when it contains none and every
	// commit is unreleased.
	NearestRelease *string `json:"nearest_release"`
	// Commits are newest first.
	Commits  []UnreleasedCommit `json:"commits"`
	Coverage Coverage           `json:"coverage"`
}

// ReadUnreleased lists the unreleased commits of the releasable the
// absolute directory dir selects. The range is bounded by the nearest
// release this checkout contains, while the latest release reported is the
// releasable's latest, which this checkout may not contain.
func ReadUnreleased(e *strictcli.Effects, dir string, fork Fork) (Unreleased, error) {
	s, err := selectAt(e, dir, fork)
	if err != nil {
		return Unreleased{}, err
	}
	if err := s.requireReleasable("unreleased"); err != nil {
		return Unreleased{}, err
	}
	head, err := s.repo.Head()
	if err != nil {
		return Unreleased{}, err
	}
	latest, err := s.record().Latest(head)
	if err != nil {
		return Unreleased{}, err
	}
	u, err := s.readUnreleased()
	if err != nil {
		return Unreleased{}, err
	}
	out := Unreleased{Releasable: s.releasable.Name, LatestFields: latestOf(latest), Commits: []UnreleasedCommit{}, Coverage: u.coverage()}
	if u.nearest != nil {
		v := u.nearest.Version.String()
		out.NearestRelease = &v
	}
	for _, sha := range u.scoped {
		summary, err := s.repo.Summarize(sha)
		if err != nil {
			return Unreleased{}, err
		}
		out.Commits = append(out.Commits, UnreleasedCommit{
			Hash:    sha,
			Subject: summary.Subject,
			Author:  summary.Author,
			Date:    summary.Date,
			Exempt:  u.exempt[sha],
			Covered: u.covered[sha],
		})
	}
	return out, nil
}
